import { Host, h, Component, Prop, type ComponentInterface } from '@stencil/core';
import { useIcon } from '../runtime';

@Component({
  tag: 'ks-icon-loading',
  styleUrls: ['../styles/index.css', '../styles/spin.css'],
  shadow: true,
})
export class KsIconLoading implements ComponentInterface {
  ['ks-icon-name']: string = 'ks-icon-loading';

  @Prop() size: string | number = 16;
  @Prop() color: string = 'currentColor';
  /**
   * @deprecated
   */
  @Prop() strokeWidth: string | number;
  /**
   * @deprecated
   */
  @Prop() absoluteStrokeWidth: boolean = false;

  render() {
    const icon = useIcon({ size: this.size, color: this.color });

    return (
      <Host class="ks-icon" ks-icon>
        <svg xmlns="http://www.w3.org/2000/svg" width={icon.width} height={icon.height} viewBox="0 0 48 48" fill="none">
          <path
            d="M4.491 24a19.51 19.51 0 0 0 19.507 19.507A19.51 19.51 0 0 0 43.505 24 19.51 19.51 0 0 0 23.998 4.493"
            stroke={icon.color}
            stroke-width={icon.strokeWidth}
            stroke-linecap="round"
          ></path>
          <animation from="transform: rotate(0)" to="transform: rotate(360deg)"></animation>
        </svg>
      </Host>
    );
  }
}
